CREATE DATABASE IF NOT EXISTS coderbot CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE coderbot;
CREATE TABLE IF NOT EXISTS students(id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(16) NOT NULL UNIQUE, name VARCHAR(16) NOT NULL, avatar VARCHAR(8) NOT NULL DEFAULT '🤖', pin_hash VARCHAR(255) NOT NULL, `pin` VARCHAR(4) NULL, settings TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, last_login TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS progress(student_id INT NOT NULL, level TINYINT NOT NULL, stars TINYINT NOT NULL DEFAULT 0, best_cards SMALLINT NOT NULL DEFAULT 0, best_secs INT NULL, attempts INT NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(student_id,level), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS plays(id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, level TINYINT NOT NULL, cards SMALLINT NOT NULL, secs INT NULL, result ENUM('win','bug','out','short') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(student_id), INDEX(level), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(30) NOT NULL UNIQUE, `password` VARCHAR(100) NULL, pass_hash VARCHAR(255) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS throttle(k VARCHAR(120) NOT NULL PRIMARY KEY, fails INT NOT NULL DEFAULT 0, first_at DATETIME NOT NULL, locked_until DATETIME NULL) ENGINE=InnoDB;
